CREATE OR REPLACE FUNCTION public.audit_capture_row_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_old jsonb; v_new jsonb; v_club uuid; v_actor uuid:=auth.uid(); v_entity_id text; v_action text;
begin
  v_old:=case when tg_op in ('UPDATE','DELETE') then public.audit_redact_json_v1(to_jsonb(old)) else null end;
  v_new:=case when tg_op in ('INSERT','UPDATE') then public.audit_redact_json_v1(to_jsonb(new)) else null end;
  v_club:=coalesce(nullif(v_new->>'club_id','')::uuid,nullif(v_old->>'club_id','')::uuid);
  if v_club is null then if tg_op='DELETE' then return old; else return new; end if; end if;
  v_entity_id:=coalesce(v_new->>'id',v_old->>'id',v_new->>'profile_id',v_old->>'profile_id',v_new->>'member_id',v_old->>'member_id',v_new->>'permission_key',v_old->>'permission_key',v_new->>'module_code',v_old->>'module_code');
  v_action:=case tg_op when 'INSERT' then 'created' when 'UPDATE' then 'updated' when 'DELETE' then 'deleted' else lower(tg_op) end;
  insert into public.audit_log(club_id,actor_id,action,entity_type,entity_id,before_data,after_data,created_at)
  values(v_club,v_actor,v_action,tg_table_name,v_entity_id,v_old,v_new,now());
  if tg_op='DELETE' then return old; end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.emit_domain_event(target_club uuid, event_name text, aggregate_type text, aggregate_id uuid, payload jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare new_id uuid; v_module text; v_permission text; v_title text; v_body text; v_priority text; r record;
begin
  if auth.uid() is null or not public.has_club_access(target_club) then raise exception 'Sem acesso ao clube.'; end if;
  v_module:=public.notification_module_code(aggregate_type);
  v_permission:=public.notification_module_permission(aggregate_type);
  v_title:=coalesce(nullif(payload->>'title',''),event_name);
  v_body:=coalesce(nullif(payload->>'description',''),v_title);
  v_priority:=case when payload->>'priority' in ('low','normal','high','urgent') then payload->>'priority' else 'normal' end;
  insert into public.domain_events(club_id,event_name,aggregate_type,aggregate_id,actor_id,payload) values(target_club,event_name,aggregate_type,aggregate_id,auth.uid(),coalesce(payload,'{}'::jsonb)) returning id into new_id;
  insert into public.activity_feed(club_id,actor_id,activity_type,title,description,entity_type,entity_id,metadata) values(target_club,auth.uid(),v_module,v_title,payload->>'description',aggregate_type,aggregate_id,coalesce(payload,'{}'::jsonb)||jsonb_build_object('event_name',event_name,'module_code',v_module,'domain_event_id',new_id));
  for r in select cm.profile_id from public.club_memberships cm where cm.club_id=target_club and cm.active=true loop
    if v_permission is null or public.profile_has_club_permission(target_club,r.profile_id,v_permission) then
      if coalesce((select np.in_app_enabled from public.notification_preferences np where np.club_id=target_club and np.profile_id=r.profile_id and np.module_code=v_module),true) then
        insert into public.notifications(club_id,profile_id,title,body,notification_type,module_code,priority,entity_type,entity_id,action_route,metadata,domain_event_id) values(target_club,r.profile_id,v_title,v_body,event_name,v_module,v_priority,aggregate_type,aggregate_id,payload->>'route',coalesce(payload,'{}'::jsonb),new_id);
      end if;
    end if;
  end loop;
  return new_id;
end
$function$

CREATE OR REPLACE FUNCTION public.inventory_count_finalize_v1(target_club uuid, p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record;
  s public.inventory_count_sessions%rowtype;
  adjusted int:=0;
  total_diff numeric:=0;
  value_diff numeric:=0;
begin
  if not public.has_club_permission(target_club,'performInventoryCount') then
    raise exception 'Sem permissão para concluir inventário físico.';
  end if;
  select * into s from public.inventory_count_sessions
  where id=p_session and club_id=target_club and status in ('counting','review')
  for update;
  if not found then raise exception 'Sessão não encontrada ou já concluída.'; end if;
  if exists(select 1 from public.inventory_count_items where session_id=p_session and counted_qty is null) then
    raise exception 'Existem artigos por contar.';
  end if;
  if exists(select 1 from public.inventory_count_items where session_id=p_session and counted_qty<0) then
    raise exception 'Existem quantidades negativas na contagem.';
  end if;

  if s.location_id is not null then
    perform set_config('bob.skip_stock_balance_sync','1',true);
  end if;

  for r in select * from public.inventory_count_items where session_id=p_session loop
    if r.difference<>0 then
      if s.location_id is null then
        if r.variant_id is null then
          update public.products set current_stock=r.counted_qty
          where id=r.product_id and club_id=target_club;
        else
          update public.product_variants set current_stock=r.counted_qty
          where id=r.variant_id and product_id=r.product_id;
        end if;
      else
        -- O teórico é o saldo do local; substituir pelo contado equivale a aplicar a diferença.
        perform public.inventory_balance_apply_internal_v1(
          target_club,r.product_id,r.variant_id,s.location_id,r.difference,0
        );
        if r.variant_id is null then
          update public.products p
          set current_stock=(
            select coalesce(sum(b.quantity),0) from public.inventory_stock_balances b
            where b.club_id=target_club and b.product_id=p.id and b.variant_id is null
          )
          where p.id=r.product_id and p.club_id=target_club;
        else
          update public.product_variants pv
          set current_stock=(
            select coalesce(sum(b.quantity),0) from public.inventory_stock_balances b
            where b.club_id=target_club and b.product_id=r.product_id and b.variant_id=pv.id
          )
          where pv.id=r.variant_id and pv.product_id=r.product_id;
        end if;
      end if;

      insert into public.stock_movements(
        club_id,product_id,variant_id,kind,quantity,unit_cost,notes,created_by,
        from_location_id,to_location_id
      ) values (
        target_club,r.product_id,r.variant_id,'adjustment',r.difference,r.unit_cost,
        'Ajuste por inventário físico '||p_session::text,auth.uid(),
        case when r.difference<0 then s.location_id else null end,
        case when r.difference>0 then s.location_id else null end
      );
      adjusted:=adjusted+1;
      total_diff:=total_diff+r.difference;
      value_diff:=value_diff+(r.difference*r.unit_cost);
    end if;
  end loop;

  update public.products p
  set current_stock=(select coalesce(sum(pv.current_stock),0) from public.product_variants pv where pv.product_id=p.id and pv.active=true)
  where p.club_id=target_club
    and exists(select 1 from public.inventory_count_items i where i.session_id=p_session and i.product_id=p.id and i.variant_id is not null);

  if s.location_id is not null then
    perform set_config('bob.skip_stock_balance_sync','0',true);
  end if;

  update public.inventory_count_sessions
  set status='completed',completed_by=auth.uid(),completed_at=now()
  where id=p_session and club_id=target_club;

  return jsonb_build_object(
    'adjusted_items',adjusted,
    'net_quantity_difference',total_diff,
    'value_difference',value_diff,
    'location_id',s.location_id
  );
end $function$

CREATE OR REPLACE FUNCTION public.inventory_variant_balance_sync_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_old_stock numeric:=0;
  v_old_reserved numeric:=0;
  v_club uuid;
  v_area text;
  v_location uuid;
begin
  if coalesce(current_setting('bob.skip_stock_balance_sync',true),'')='1' then return new; end if;
  select club_id,inventory_area into v_club,v_area from public.products where id=new.product_id;
  if tg_op='UPDATE' then
    v_old_stock:=coalesce(old.current_stock,0);
    v_old_reserved:=coalesce(old.reserved_stock,0);
  end if;
  v_location:=public.inventory_default_location_v1(v_club,v_area);
  -- Ao aparecer a primeira variante, o stock passa a ser controlado pelas variantes.
  delete from public.inventory_stock_balances
  where club_id=v_club and product_id=new.product_id and variant_id is null;
  perform public.inventory_balance_apply_internal_v1(
    v_club,new.product_id,new.id,v_location,
    coalesce(new.current_stock,0)-v_old_stock,
    coalesce(new.reserved_stock,0)-v_old_reserved
  );
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.member_status_timeline_trigger_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op='INSERT' then
    insert into public.member_status_history(club_id,member_id,old_status,new_status,changed_at,changed_by)
    values(new.club_id,new.id,null,new.status,coalesce(new.created_at,now()),auth.uid());

    perform public.member_timeline_append_v1(
      new.club_id,
      new.id,
      'member_created',
      'Membro criado',
      new.status::text,
      coalesce(new.joined_at,current_date),
      'club',
      'member',
      new.id
    );

    if new.prospect_joined_at is not null then
      perform public.member_timeline_append_v1(
        new.club_id,new.id,'prospect_joined','Entrada como Prospect',null,
        new.prospect_joined_at,'club','member',new.id
      );
    end if;

    if new.full_colors_at is not null then
      perform public.member_timeline_append_v1(
        new.club_id,new.id,'full_colors','Full Colors',null,
        new.full_colors_at,'club','member',new.id
      );
    end if;

    return new;
  end if;

  if old.status is distinct from new.status then
    insert into public.member_status_history(club_id,member_id,old_status,new_status,changed_at,changed_by)
    values(new.club_id,new.id,old.status,new.status,now(),auth.uid());

    perform public.member_timeline_append_v1(
      new.club_id,
      new.id,
      'status_change',
      'Estado alterado para '||coalesce(new.status::text,'—'),
      'Anterior: '||coalesce(old.status::text,'—'),
      current_date,
      'club',
      'member',
      new.id
    );
  end if;

  if old.prospect_joined_at is distinct from new.prospect_joined_at
     and new.prospect_joined_at is not null then
    perform public.member_timeline_append_v1(
      new.club_id,new.id,'prospect_joined','Entrada como Prospect',null,
      new.prospect_joined_at,'club','member',new.id
    );
  end if;

  if old.full_colors_at is distinct from new.full_colors_at
     and new.full_colors_at is not null then
    perform public.member_timeline_append_v1(
      new.club_id,new.id,'full_colors','Full Colors',null,
      new.full_colors_at,'club','member',new.id
    );
  end if;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.protect_profile_privileges()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller_role public.user_role;
begin
  select role into caller_role
  from public.profiles
  where id = auth.uid();

  if caller_role = 'admin' and new.role = 'super_admin' then
    raise exception 'Apenas um superadministrador pode atribuir este perfil.';
  end if;

  if old.id = auth.uid() and old.active = true and new.active = false then
    raise exception 'Não é possível desativar a própria conta.';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.retry_financial_ocr_job_v1(target_club uuid, p_job uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare j public.financial_ocr_jobs%rowtype; v_allowed boolean;
begin
  if auth.uid() is null then raise exception 'Sessão inválida.'; end if;
  select * into j from public.financial_ocr_jobs where id=p_job and club_id=target_club for update;
  if not found then raise exception 'Pedido OCR não encontrado.'; end if;
  v_allowed:=case when j.source_kind='bar_import' then public.has_club_permission(target_club,'manageBar') else (public.has_club_permission(target_club,'createTreasuryMovement') or public.has_club_permission(target_club,'approveExpenseRequests')) end;
  if not v_allowed then raise exception 'Sem autorização para repetir este OCR.'; end if;
  if j.storage_path is null then raise exception 'Pedido OCR sem ficheiro.'; end if;
  if j.status in ('processing','confirmed','cancelled') then raise exception 'O pedido OCR não pode ser repetido neste estado.'; end if;
  update public.financial_ocr_jobs set status='pending',error_message=null,started_at=null,completed_at=null where id=p_job;
end; $function$

CREATE OR REPLACE FUNCTION public.save_financial_ocr_review_v1(target_club uuid, p_job uuid, p_supplier_name text, p_supplier_tax_id text, p_document_number text, p_document_date date, p_currency text, p_subtotal numeric, p_tax_total numeric, p_total numeric, p_payment_method text, p_confidence numeric, p_line_items jsonb, p_warnings jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare j public.financial_ocr_jobs%rowtype; v_allowed boolean;
begin
  if auth.uid() is null then raise exception 'Sessão inválida.'; end if;
  select * into j from public.financial_ocr_jobs where id=p_job and club_id=target_club for update;
  if not found then raise exception 'Pedido OCR não encontrado.'; end if;
  v_allowed:=case when j.source_kind='bar_import' then public.has_club_permission(target_club,'manageBar') else (public.has_club_permission(target_club,'createTreasuryMovement') or public.has_club_permission(target_club,'approveExpenseRequests')) end;
  if not v_allowed then raise exception 'Sem autorização para rever este OCR.'; end if;
  if j.status not in ('ready','reviewed') then raise exception 'O OCR ainda não está pronto para revisão.'; end if;
  if p_line_items is null or jsonb_typeof(p_line_items)<>'array' then raise exception 'Linhas OCR inválidas.'; end if;
  if p_warnings is null or jsonb_typeof(p_warnings)<>'array' then raise exception 'Avisos OCR inválidos.'; end if;
  update public.financial_ocr_jobs set supplier_name=nullif(btrim(coalesce(p_supplier_name,'')),''),supplier_tax_id=nullif(btrim(coalesce(p_supplier_tax_id,'')),''),document_number=nullif(btrim(coalesce(p_document_number,'')),''),document_date=p_document_date,currency=upper(nullif(btrim(coalesce(p_currency,'')),'')),subtotal=p_subtotal,tax_total=p_tax_total,total=p_total,payment_method=nullif(btrim(coalesce(p_payment_method,'')),''),confidence=case when p_confidence is null then confidence else greatest(0,least(1,p_confidence)) end,line_items=p_line_items,warnings=p_warnings,status='reviewed',reviewed_at=now(),reviewed_by=auth.uid() where id=p_job;
end; $function$
